ALTER TABLE public.photos ADD COLUMN IF NOT EXISTS preview_path text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS looking_for text;
ALTER TABLE public.messages ADD COLUMN IF NOT EXISTS unsent boolean NOT NULL DEFAULT false;
ALTER TABLE public.messages ADD COLUMN IF NOT EXISTS read_at timestamptz;
CREATE TABLE public.album_access_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), album_id uuid NOT NULL REFERENCES public.photo_albums(id) ON DELETE CASCADE, requester_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','declined')), note text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(album_id,requester_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.album_access_requests TO authenticated;
GRANT ALL ON public.album_access_requests TO service_role;
ALTER TABLE public.album_access_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "participants read album requests" ON public.album_access_requests FOR SELECT TO authenticated USING (requester_id=auth.uid() OR EXISTS(SELECT 1 FROM public.photo_albums a WHERE a.id=album_id AND a.user_id=auth.uid()));
CREATE POLICY "request private album" ON public.album_access_requests FOR INSERT TO authenticated WITH CHECK(requester_id=auth.uid() AND status='pending' AND EXISTS(SELECT 1 FROM public.photo_albums a JOIN public.profiles p ON p.id=a.user_id WHERE a.id=album_id AND a.user_id<>auth.uid() AND NOT p.banned));
CREATE POLICY "owner responds to album request" ON public.album_access_requests FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.photo_albums a WHERE a.id=album_id AND a.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.photo_albums a WHERE a.id=album_id AND a.user_id=auth.uid()));
CREATE POLICY "owner revokes album request" ON public.album_access_requests FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.photo_albums a WHERE a.id=album_id AND a.user_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.can_read_photo(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.photos ph JOIN public.profiles p ON p.id=ph.user_id LEFT JOIN public.photo_albums a ON a.id=ph.album_id WHERE ph.path=_path AND (ph.user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (NOT p.banned AND ((NOT ph.is_private AND (a.id IS NULL OR NOT a.is_private)) OR EXISTS(SELECT 1 FROM public.album_access_requests r WHERE r.album_id=ph.album_id AND r.requester_id=auth.uid() AND r.status='approved'))))) $$;
REVOKE ALL ON FUNCTION public.can_read_photo(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_read_photo(text) TO authenticated;
DROP POLICY IF EXISTS "photos read" ON storage.objects;
CREATE POLICY "photos read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='photos' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.can_read_photo(name)));
DROP POLICY IF EXISTS "photos readable" ON public.photos;
CREATE POLICY "photos readable" ON public.photos FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=user_id AND NOT p.banned));
DROP POLICY IF EXISTS "albums readable" ON public.photo_albums;
CREATE POLICY "albums readable" ON public.photo_albums FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=user_id AND NOT p.banned));
CREATE POLICY "blurred previews read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='photo-previews' AND EXISTS(SELECT 1 FROM public.photos ph JOIN public.profiles p ON p.id=ph.user_id WHERE ph.preview_path=name AND NOT p.banned));
CREATE POLICY "blurred previews upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='photo-previews' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "blurred previews delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='photo-previews' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE OR REPLACE FUNCTION public.sync_photo_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.album_id IS NOT NULL THEN SELECT a.is_private INTO NEW.is_private FROM public.photo_albums a WHERE a.id=NEW.album_id AND a.user_id=NEW.user_id; IF NOT FOUND THEN RAISE EXCEPTION 'Album does not belong to you'; END IF; ELSE NEW.is_private=false; END IF; RETURN NEW; END $$;
CREATE TRIGGER sync_photo_privacy BEFORE INSERT OR UPDATE OF album_id,is_private ON public.photos FOR EACH ROW EXECUTE FUNCTION public.sync_photo_privacy();
UPDATE public.photos ph SET is_private=COALESCE((SELECT a.is_private FROM public.photo_albums a WHERE a.id=ph.album_id),false);
CREATE OR REPLACE FUNCTION public.keep_connection_participants() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.requester<>OLD.requester OR NEW.addressee<>OLD.addressee THEN RAISE EXCEPTION 'Participants cannot be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER keep_connection_participants BEFORE UPDATE ON public.connections FOR EACH ROW EXECUTE FUNCTION public.keep_connection_participants();
CREATE OR REPLACE FUNCTION public.keep_album_request_participants() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.album_id<>OLD.album_id OR NEW.requester_id<>OLD.requester_id THEN RAISE EXCEPTION 'Request participants cannot be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER keep_album_request_participants BEFORE UPDATE ON public.album_access_requests FOR EACH ROW EXECUTE FUNCTION public.keep_album_request_participants();
DROP POLICY IF EXISTS "respond request" ON public.connections;
CREATE POLICY "respond request" ON public.connections FOR UPDATE TO authenticated USING(addressee=auth.uid() AND status='pending') WITH CHECK(addressee=auth.uid() AND status IN ('accepted','declined'));
DROP POLICY IF EXISTS "send request" ON public.connections;
CREATE POLICY "send request" ON public.connections FOR INSERT TO authenticated WITH CHECK(requester=auth.uid() AND addressee<>auth.uid() AND status='pending' AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=addressee AND NOT p.banned));
CREATE OR REPLACE FUNCTION public.increment_message_view(message_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.messages; BEGIN SELECT * INTO m FROM public.messages WHERE id=message_id FOR UPDATE; IF NOT FOUND OR NOT public.is_connected(m.connection_id) OR m.sender=auth.uid() OR m.unsent OR (m.expires_at IS NOT NULL AND m.expires_at<=now()) THEN RETURN false; END IF; IF m.max_views IS NOT NULL AND m.view_count>=m.max_views THEN RETURN false; END IF; UPDATE public.messages SET view_count=view_count+1,attachment_viewed_at=now() WHERE id=message_id; RETURN true; END $$;
CREATE OR REPLACE FUNCTION public.mark_chat_read(_connection_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_connected(_connection_id) THEN RAISE EXCEPTION 'Chat unavailable'; END IF; UPDATE public.messages SET read_at=now() WHERE connection_id=_connection_id AND sender<>auth.uid() AND read_at IS NULL; END $$;
CREATE OR REPLACE FUNCTION public.unsend_message(_message_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.messages SET unsent=true,body=NULL,attachment_path=NULL,attachment_type=NULL,attachment_name=NULL WHERE id=_message_id AND sender=auth.uid() AND public.is_connected(connection_id); IF NOT FOUND THEN RAISE EXCEPTION 'Message unavailable'; END IF; END $$;
REVOKE ALL ON FUNCTION public.increment_message_view(uuid),public.mark_chat_read(uuid),public.unsend_message(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.increment_message_view(uuid),public.mark_chat_read(uuid),public.unsend_message(uuid) TO authenticated;
REVOKE UPDATE ON public.messages FROM authenticated;
DROP POLICY IF EXISTS "read messages" ON public.messages;
CREATE POLICY "read messages" ON public.messages FOR SELECT TO authenticated USING(public.is_connected(connection_id) AND (expires_at IS NULL OR expires_at>now()));
ALTER PUBLICATION supabase_realtime ADD TABLE public.album_access_requests;